CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS wedding (id int PRIMARY KEY DEFAULT 1 CHECK(id=1), bride text NOT NULL DEFAULT 'Harini', groom text NOT NULL DEFAULT 'Roshan', contact text NOT NULL DEFAULT '', date date, venue text NOT NULL DEFAULT 'To be announced');
INSERT INTO wedding(id) VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS admins(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password text NOT NULL, role text NOT NULL DEFAULT 'admin');
CREATE TABLE IF NOT EXISTS sessions(token text PRIMARY KEY, admin_id uuid NOT NULL REFERENCES admins(id), expires timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key text PRIMARY KEY, count int NOT NULL, expires timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS households(id uuid PRIMARY KEY, token_hash text UNIQUE NOT NULL, name text NOT NULL, contact text NOT NULL, mobile text NOT NULL, email text NOT NULL DEFAULT '', category text NOT NULL DEFAULT '', tags text[] NOT NULL DEFAULT '{}', expected int NOT NULL CHECK(expected>0), additional int NOT NULL DEFAULT 0 CHECK(additional>=0), status text NOT NULL DEFAULT 'Not Responded', delivery text NOT NULL DEFAULT 'Not Planned', assignee text NOT NULL DEFAULT '', visit_date date, visited_date date, notes text NOT NULL DEFAULT '', travel jsonb NOT NULL DEFAULT '{}', stay jsonb NOT NULL DEFAULT '{}', version int NOT NULL DEFAULT 0, sent_at timestamptz, opened_at timestamptz, archived boolean NOT NULL DEFAULT false);
-- Match the phoneKey normalization used by imports, including the 00 dial prefix.
CREATE UNIQUE INDEX IF NOT EXISTS households_mobile_unique ON households ((regexp_replace(regexp_replace(split_part(regexp_replace(mobile, '^tel:', '', 'i'), ';', 1), '[^0-9]', '', 'g'), '^00', '')));
CREATE TABLE IF NOT EXISTS members(id uuid PRIMARY KEY, household_id uuid NOT NULL REFERENCES households(id) ON DELETE CASCADE, name text NOT NULL, attendance text NOT NULL DEFAULT 'Maybe' CHECK(attendance IN ('Yes','No','Maybe')), age_group text NOT NULL DEFAULT 'Adult', accessibility text NOT NULL DEFAULT '', travel jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS member_phones(phone text PRIMARY KEY CHECK(phone ~ '^[0-9]{5,}$'), display text NOT NULL, member_id uuid NOT NULL REFERENCES members(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS member_phones_member_idx ON member_phones(member_id);
CREATE TABLE IF NOT EXISTS locations(id uuid PRIMARY KEY, household_id uuid NOT NULL REFERENCES households(id) ON DELETE CASCADE, kind text NOT NULL, city text NOT NULL, area text NOT NULL DEFAULT '', state text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS events(id uuid PRIMARY KEY, name text NOT NULL, starts timestamptz, ends timestamptz, location text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '');
ALTER TABLE events ADD COLUMN IF NOT EXISTS event_date date, ADD COLUMN IF NOT EXISTS tamil_date text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS time_label text NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS event_rsvps(event_id uuid REFERENCES events(id), member_id uuid REFERENCES members(id) ON DELETE CASCADE, attendance text NOT NULL, PRIMARY KEY(event_id, member_id));
CREATE TABLE IF NOT EXISTS properties(id uuid PRIMARY KEY, name text NOT NULL, address text NOT NULL DEFAULT '', contact text NOT NULL DEFAULT '', instructions text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS rooms(id uuid PRIMARY KEY, property_id uuid NOT NULL REFERENCES properties(id), name text NOT NULL, capacity int NOT NULL CHECK(capacity>0), UNIQUE(property_id,name));
CREATE TABLE IF NOT EXISTS allocations(id uuid PRIMARY KEY, household_id uuid NOT NULL REFERENCES households(id), room_id uuid NOT NULL REFERENCES rooms(id), people int NOT NULL CHECK(people>0), check_in date NOT NULL, check_out date NOT NULL, status text NOT NULL DEFAULT 'Allocated', published boolean NOT NULL DEFAULT false, CHECK(check_out>check_in), EXCLUDE USING gist(room_id WITH =, daterange(check_in,check_out,'[)') WITH &&) WHERE(status <> 'Cancelled'));
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY, household_id uuid NOT NULL REFERENCES households(id) ON DELETE CASCADE, type text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, delivered_at timestamptz, viewed_at timestamptz);
CREATE TABLE IF NOT EXISTS activity(id uuid PRIMARY KEY, household_id uuid REFERENCES households(id) ON DELETE CASCADE, actor text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS alerts(id uuid PRIMARY KEY, household_id uuid NOT NULL REFERENCES households(id), body text NOT NULL, resolved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trips(id uuid PRIMARY KEY, name text NOT NULL, date date, assignee text NOT NULL, status text NOT NULL DEFAULT 'Planned');
CREATE TABLE IF NOT EXISTS stops(id uuid PRIMARY KEY, trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE, household_id uuid NOT NULL REFERENCES households(id), location_id uuid NOT NULL REFERENCES locations(id), status text NOT NULL DEFAULT 'Pending', UNIQUE(trip_id,household_id));
CREATE TABLE IF NOT EXISTS dress_categories(id uuid PRIMARY KEY, name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200));
CREATE UNIQUE INDEX IF NOT EXISTS dress_categories_name_unique ON dress_categories(lower(trim(name)));
CREATE TABLE IF NOT EXISTS household_dress(household_id uuid PRIMARY KEY REFERENCES households(id) ON DELETE CASCADE, category_id uuid NOT NULL REFERENCES dress_categories(id));
CREATE TABLE IF NOT EXISTS dress_classes(id uuid PRIMARY KEY, name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200));
CREATE UNIQUE INDEX IF NOT EXISTS dress_classes_name_unique ON dress_classes(lower(trim(name)));
CREATE TABLE IF NOT EXISTS dress_sizes(id uuid PRIMARY KEY, name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200));
CREATE UNIQUE INDEX IF NOT EXISTS dress_sizes_name_unique ON dress_sizes(lower(trim(name)));
CREATE TABLE IF NOT EXISTS member_dress(member_id uuid PRIMARY KEY REFERENCES members(id) ON DELETE CASCADE, category_id uuid REFERENCES dress_categories(id), class_id uuid REFERENCES dress_classes(id), size_id uuid REFERENCES dress_sizes(id), CHECK(category_id IS NOT NULL OR class_id IS NOT NULL OR size_id IS NOT NULL));
